def first_unique(s: str) -> str | None:
    """Return the first character in *s* that appears exactly once.
    Case‑sensitive.  If no such character exists (including the empty string),
    return ``None``.
    """
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    for ch in s:
        if counts[ch] == 1:
            return ch
    return None


# ---- tests --------------------------------------------------------------
import pytest

def test_first_unique_empty():
    assert first_unique("") is None

def test_first_unique_aabbc():
    assert first_unique("aabbc") == "c"

def test_first_unique_swiss():
    # 'S' appears once, 'w' appears once, but 'S' comes first
    assert first_unique("Swiss") == "S"

def test_first_unique_abccba():
    assert first_unique("abccba") is None
